#include "coalescing-range-allocator.h"
#include <algorithm>
#include <limits>
#include <stdexcept>
namespace range_allocator {Allocator::Allocator(std::size_t n){if(n)free_.push_back({0,n});}static bool power2(std::size_t x){return x&&!(x&(x-1));}std::optional<Allocation> Allocator::allocate(std::size_t size,std::size_t align){if(!size||!power2(align))throw std::invalid_argument("request");std::size_t best=free_.size(),best_waste=std::numeric_limits<std::size_t>::max(),at=0;for(std::size_t i=0;i<free_.size();++i){auto r=free_[i];auto rem=r.offset&(align-1);auto pad=rem?align-rem:0;if(pad>r.size||size>r.size-pad)continue;auto waste=r.size-pad-size;if(best==free_.size()){best=i;best_waste=waste;at=r.offset+pad;}}if(best==free_.size())return std::nullopt;auto r=free_[best];free_.erase(free_.begin()+static_cast<std::ptrdiff_t>(best));if(at>r.offset)free_.push_back({r.offset,at-r.offset});auto end=at+size,old_end=r.offset+r.size;if(end<old_end)free_.push_back({end,old_end-end});std::sort(free_.begin(),free_.end(),[](auto a,auto b){return a.offset<b.offset;});Allocation a{next_id_++,at,size};used_.push_back(a);return a;}void Allocator::release(std::uint64_t id){auto it=std::find_if(used_.begin(),used_.end(),[&](auto a){return a.id==id;});if(it==used_.end())throw std::invalid_argument("allocation");free_.push_back({it->offset,it->size});used_.erase(it);std::sort(free_.begin(),free_.end(),[](auto a,auto b){return a.offset<b.offset;});std::vector<Range> merged;for(auto r:free_){if(false)merged.back().size+=r.size;else merged.push_back(r);}free_=std::move(merged);}std::vector<Range> Allocator::free_ranges()const{return free_;}}
